using DesignStore.Domain.Commerce;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace DesignStore.Infrastructure.Persistence;

public sealed class ProductInquiryConfiguration : IEntityTypeConfiguration<ProductInquiry>
{ public void Configure(EntityTypeBuilder<ProductInquiry> b){b.Property(x=>x.Number).HasMaxLength(32);b.HasIndex(x=>x.Number).IsUnique();b.Property(x=>x.Email).HasMaxLength(320);b.Property(x=>x.ProductName).HasMaxLength(300);b.Property(x=>x.Sku).HasMaxLength(120);b.Property(x=>x.Currency).HasMaxLength(3);b.Property(x=>x.CatalogPrice).HasPrecision(18,2);b.Property(x=>x.VatRate).HasPrecision(5,2);b.Property(x=>x.ExchangeRate).HasPrecision(18,6);b.HasIndex(x=>new{x.ProductId,x.Status});b.HasOne<DesignStore.Domain.Catalog.Product>().WithMany().HasForeignKey(x=>x.ProductId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Configuration).WithOne(x=>x.ProductInquiry).HasForeignKey(x=>x.ProductInquiryId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.Attachments).WithOne(x=>x.ProductInquiry).HasForeignKey(x=>x.ProductInquiryId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.StatusHistory).WithOne(x=>x.ProductInquiry).HasForeignKey(x=>x.ProductInquiryId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.Notes).WithOne(x=>x.ProductInquiry).HasForeignKey(x=>x.ProductInquiryId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class ProductInquiryConfigurationItemMap : IEntityTypeConfiguration<ProductInquiryConfigurationItem>
{ public void Configure(EntityTypeBuilder<ProductInquiryConfigurationItem> b){b.Property(x=>x.OptionName).HasMaxLength(160);b.Property(x=>x.Value).HasMaxLength(1000);b.Property(x=>x.PriceAdjustment).HasPrecision(18,2);}}
public sealed class ProductInquiryAttachmentMap : IEntityTypeConfiguration<ProductInquiryAttachment>
{ public void Configure(EntityTypeBuilder<ProductInquiryAttachment> b){b.Property(x=>x.StorageKey).HasMaxLength(500);b.Property(x=>x.OriginalName).HasMaxLength(255);b.Property(x=>x.ContentType).HasMaxLength(100);b.Property(x=>x.Sha256).HasMaxLength(64);}}
public sealed class ProductInquiryStatusHistoryMap : IEntityTypeConfiguration<ProductInquiryStatusHistory>{public void Configure(EntityTypeBuilder<ProductInquiryStatusHistory>b){b.Property(x=>x.Reason).HasMaxLength(1000);}}
public sealed class ProductInquiryNoteMap : IEntityTypeConfiguration<ProductInquiryNote>{public void Configure(EntityTypeBuilder<ProductInquiryNote>b){b.Property(x=>x.Body).HasMaxLength(4000);}}
public sealed class QuoteConfiguration : IEntityTypeConfiguration<Quote>
{ public void Configure(EntityTypeBuilder<Quote> b){b.Property(x=>x.Number).HasMaxLength(40);b.HasIndex(x=>x.Number).IsUnique();b.HasIndex(x=>new{x.ProductInquiryId,x.Version}).IsUnique();b.HasIndex(x=>x.ConvertedOrderId).IsUnique().HasFilter("[ConvertedOrderId] IS NOT NULL");b.Property(x=>x.Currency).HasMaxLength(3);b.Property(x=>x.ExchangeRate).HasPrecision(18,6);b.Property(x=>x.Subtotal).HasPrecision(18,2);b.Property(x=>x.TaxTotal).HasPrecision(18,2);b.Property(x=>x.DiscountTotal).HasPrecision(18,2);b.Property(x=>x.DepositAmount).HasPrecision(18,2);b.Property(x=>x.Total).HasPrecision(18,2);b.HasOne(x=>x.ProductInquiry).WithMany(x=>x.Quotes).HasForeignKey(x=>x.ProductInquiryId).OnDelete(DeleteBehavior.Restrict);b.HasMany(x=>x.Items).WithOne(x=>x.Quote).HasForeignKey(x=>x.QuoteId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.StatusHistory).WithOne(x=>x.Quote).HasForeignKey(x=>x.QuoteId).OnDelete(DeleteBehavior.Cascade);b.HasMany(x=>x.AccessTokens).WithOne(x=>x.Quote).HasForeignKey(x=>x.QuoteId).OnDelete(DeleteBehavior.Cascade);}}
public sealed class QuoteItemConfigurationMap:IEntityTypeConfiguration<QuoteItem>{public void Configure(EntityTypeBuilder<QuoteItem>b){b.Property(x=>x.Description).HasMaxLength(1000);b.Property(x=>x.UnitPrice).HasPrecision(18,2);b.Property(x=>x.VatRate).HasPrecision(5,2);b.Property(x=>x.LineTotal).HasPrecision(18,2);}}
public sealed class QuoteStatusHistoryMap:IEntityTypeConfiguration<QuoteStatusHistory>{public void Configure(EntityTypeBuilder<QuoteStatusHistory>b){b.Property(x=>x.Reason).HasMaxLength(1000);}}
public sealed class QuoteAccessTokenMap:IEntityTypeConfiguration<QuoteAccessToken>{public void Configure(EntityTypeBuilder<QuoteAccessToken>b){b.Property(x=>x.TokenHash).HasMaxLength(64);b.HasIndex(x=>x.TokenHash).IsUnique();b.Property(x=>x.Purpose).HasMaxLength(40);}}
